/** Hand-maintained fixes for ids missing from the generated table. */
export const ITEM_NAME_OVERRIDES: Record<string, string> = {
  // Worlds Part II-era additions (post-extraction ids seen in real saves).
  BUI_SCRAP: 'Void Mote',
  PIRATE_PROD: 'Pirate Transponder',
  ROBOT2: 'Atlantideum'
}

/** Lowercased alphanumeric form used to join display names across data sources. */
export function normaliseItemName(name: string): string {
  return name.toLowerCase().replace(/[^a-z0-9]/g, '')
}

/**
 * Display name for a save-file item id ('^' already stripped).
 * Procedural items carry a seed suffix ('UP_LASER3#93811') — the base id
 * names the family. Unknown ids are prettified: 'FOOD_M_GRUB' -> 'Food M Grub'.
 */
export function itemDisplayName(itemId: string): string {
  const base = itemId.split('#')[0]
  const known = ITEM_NAME_OVERRIDES[base] ?? ITEM_NAMES[base]
  if (known) return known
  return base
    .split('_')
    .filter(Boolean)
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())
    .join(' ')
}
